"""Create a compact, searchable route into the integrated book additions."""
import html
import json
from pathlib import Path

BASE=Path(__file__).resolve().parent
m=json.loads((BASE/'manifest.json').read_text())
i=json.loads((BASE/'integration-manifest.json').read_text())
d=json.loads((BASE/'book-content.json').read_text())
practice=json.loads((BASE/'practice-additions.json').read_text())
qdict={q['id']:q for ch in d['chapters'] for q in ch['questions']}
e=html.escape
def booklink(key,label):
    return f'<a href="../pdf/LiveKit-Agents-Expanded-Study-Edition.pdf#page={m["page_map"][key]}">{e(label)} · p {m["page_map"][key]}</a>'

questions=[]
for qid in i['new_question_ids']:
    q=qdict[qid]
    answer=''.join('<p>'+e(t)+'</p>' for t in q['answer'])
    probes=''.join('<h4>'+e(f['question'])+'</h4><p>'+e(f['answer'])+'</p>' for f in q['followups'])
    questions.append('<article class="question" data-search="'+e((qid+' '+q['title']+' '+q['question']+' '+' '.join(q['answer'])).lower())+'"><div class="eyebrow">'+e(qid)+'</div><h2>'+e(q['title'])+'</h2><p>'+booklink('q-'+qid,'Open in the book')+'</p><details><summary>'+e(q['question'])+'</summary>'+answer+probes+'<p class="watch"><b>Watch for.</b> '+e(q['watch_for'])+'</p></details></article>')
updates=''.join('<tr><td>'+booklink('q-'+qid,qid)+'</td><td>'+e(i['update_reasons'][qid])+'</td></tr>' for qid in i['expanded_existing_ids'])
figures=''.join('<li>'+booklink('fig-'+f['id'],f['id']+' / '+f['title'])+'</li>' for f in d['figures'].values() if f['id'] in i['new_figures'])
guides=''.join('<li>'+booklink('academy-guide-'+str(n),g['title'])+'</li>' for n,g in enumerate(practice['field_guides'],1))
drills=''.join('<li>'+booklink(x['id'],x['title'])+'</li>' for x in practice['drills'])
text=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Your expanded LiveKit book</title><style>
:root{{--ink:#202b3c;--navy:#162647;--blue:#2d46d7;--teal:#087e78;--muted:#5f6f88;--line:#c9d4e8}}*{{box-sizing:border-box}}body{{background:#f1f4fa;color:var(--ink);font:16px/1.6 Arial,sans-serif;margin:0}}main{{max-width:1000px;padding:40px 28px 80px;margin:auto}}h1{{font:700 43px/1.15 Georgia,serif;color:var(--navy)}}h2,h3{{color:var(--navy);line-height:1.25}}h2{{font-size:24px}}a{{color:var(--blue)}}.eyebrow{{font-size:12px;font-weight:bold;letter-spacing:.08em;color:var(--teal)}}.stats{{display:flex;gap:13px;flex-wrap:wrap;margin:28px 0}}.stats div{{background:white;border:1px solid var(--line);padding:16px 22px;border-radius:7px}}.stats b{{display:block;font-size:28px;color:var(--blue)}}section{{margin:40px 0}}article{{background:white;border:1px solid var(--line);border-radius:7px;padding:22px;margin:18px 0}}nav{{display:flex;gap:18px;flex-wrap:wrap}}small,.scope{{color:var(--muted);font-size:14px}}summary{{cursor:pointer;font-weight:bold;color:var(--navy)}}details[open]>summary{{margin-bottom:20px}}table{{border-collapse:collapse;background:white;width:100%;font-size:14px}}td,th{{vertical-align:top;text-align:left;padding:13px;border:1px solid var(--line)}}th{{background:#edf1ff}}td:first-child{{width:150px}}input{{width:100%;padding:13px;font:inherit;border:1px solid #9eafcc;border-radius:5px}}li{{padding:7px 0}}.watch{{border-left:3px solid #a65f05;padding-left:14px}}.hidden{{display:none}}@media print{{@page{{size:A4;margin:20mm}}body{{background:white;font-size:10pt}}main{{padding:0}}nav,input{{display:none}}h1{{font-size:26pt}}article{{break-inside:avoid;border:0;border-bottom:1px solid #aaa;padding:10pt 0}}section{{break-before:page}}a{{color:var(--navy)}}}}
</style><main><div class="eyebrow">EXPANDED STUDY EDITION · 19 NOVEMBER 2026</div><h1>Your LiveKit book, with the recommended depth integrated</h1><p>Fifteen new questions, ten expanded answers, five new vector diagrams, three comparison guides and four designed failure exercises. The original fifteen chapters, existing question IDs, sixty code reviews and original figure IDs remain intact.</p><div class="stats"><div><b>{m['pages']}</b>pages</div><div><b>{m['questions']}</b>questions</div><div><b>{m['answered_followups']}</b>answered follow-ups</div><div><b>{m['vector_figures']}</b>vector diagrams</div></div><p><a href="../pdf/LiveKit-Agents-Expanded-Study-Edition.pdf">Open the full printable book</a></p><nav><a href="#questions">New questions</a><a href="#expanded">Expanded answers</a><a href="#visuals">Diagrams and guides</a><a href="#exercises">Failure exercises</a><a href="#print">Print settings</a></nav><p class="scope">The book adds original, source-checked preparation material following the public curriculum audit. SDK, RAG, graph and telephony examples remain version-scoped explanations or proposed designs. The document work did not run providers, qualify new POC features or execute the designed exercises.</p><section id="questions"><h2>Fifteen new questions</h2><p>Read tasks and turn control first, then frontend APIs, phone routing, retrieval and evaluation. Each entry links to its printed page and includes a preview.</p><label for="filter">Filter new questions by ID or topic</label><input id="filter" placeholder="Try RPC, RAG, transfer, tasks, or evaluation">{''.join(questions)}</section><section id="expanded"><h2>Ten expanded existing answers</h2><table><tr><th>Question</th><th>What was expanded</th></tr>{updates}</table></section><section id="visuals"><h2>Five new diagrams</h2><ul>{figures}</ul><h3>Three comparison guides</h3><ul>{guides}</ul></section><section id="exercises"><h2>Four failure exercises</h2><p>These are designed exercises with an approach, independent assertions and failure traps. They have not been executed as new application qualification.</p><ul>{drills}</ul></section><section id="print"><h2>Print settings</h2><p>A4 portrait, 100% / actual size, duplex, flip on the long edge. The PDF already has mirrored binding margins: 68pt inside and 46pt outside. Keep the existing page order for right-hand chapter openings and facing code/answer spreads. {m['pages']} pages use {m['sheets_duplex']} sheets when printed duplex, with the final reverse blank.</p><p>Color reinforces the study cues; textual labels and line styles retain meaning in grayscale. The question and answer body remains 10.5pt.</p><p class="scope">Application source snapshot: {e(m['commit'])}. Previous edition preserved. Current PDF SHA-256: {e(m['sha256'])}.</p></section></main><script>document.getElementById('filter').addEventListener('input',event=>{{const term=event.target.value.trim().toLowerCase();document.querySelectorAll('.question').forEach(q=>q.classList.toggle('hidden',!q.dataset.search.includes(term)));}});</script></html>'''
dest=BASE.parent/'Start-Here-Expanded-Book.html'
dest.write_text(text)
print(dest)
